#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Metas
{
    public class TalkCharacterVariant : ITalkCharacterVariant
    {
        public NamespaceID id;
        public XMLConditionList? unlock;
        public int width;
        public int height;
        public float pivotX = 0.5f;
        public float pivotY = 0.5f;
        public Vector2 widthExtend;
        public List<TalkCharacterLayer> layers = new List<TalkCharacterLayer>();

        public TalkCharacterVariant(NamespaceID id)
        {
            this.id = id;
        }

        NamespaceID ITalkCharacterVariant.ID => id;

