        int ITalkCharacterVariant.Width => width;

        int ITalkCharacterVariant.Height => height;

        float ITalkCharacterVariant.PivotX => pivotX;

        float ITalkCharacterVariant.PivotY => pivotY;

        Vector2 ITalkCharacterVariant.WidthExtend => widthExtend;

        ITalkCharacterLayer[] ITalkCharacterVariant.GetLayers() => layers.ToArray();
    }
